-- ============================================================================
-- v1357: Seed / sample data — Data Cleansing fields (v1356) for the Data Migration demo project
-- ============================================================================
-- Companion seed to v1356 (rule 18.2). Fills every tab on the 10 sample cleansing issues of project
-- SEED334-PRJ-08 (ids …-4000-a010-…, fictional "Northbridge Bank" scenario; vendor-neutral, rule 26),
-- consistent with each record's description and status: completed issues carry verification
-- details, open ones their progress so far. Person fields are plain text (fictional scenario names).
-- Values already on a record are kept — the seed only adds missing keys.
-- Prerequisites: v1356. Idempotent.
-- ============================================================================

UPDATE public.local_register_records r
SET field_values = v.vals::jsonb || COALESCE(r.field_values, '{}'::jsonb),
    updated_at = NOW()
FROM (VALUES
  ('00000000-0000-4000-a010-000000000001', $j${"issue_reference":"DQ-001","product_area":"customers_individual_and_corporate","data_object":"Customer","source_system":"Legacy core banking – Instances 1 and 2","issue_category":"duplicates","severity":"critical","blocks_migration":true,"found_during":"profiling","data_owner":"Amina Diallo","cleansing_lead":"Brian Otieno","records_checked":1427400,"records_affected":27550,"detection_rule":"Match on national ID number, or name + date of birth + mobile number\nRun across both instances and within each instance","impact_if_not_fixed":"Duplicate customers in the target\nSplit exposure and KYC across several customer numbers","affected_mapping_sheets":"DMS-CUS-01","cleansing_method":"transform_in_staging","responsible_team":"Branch operations with the data migration team","cleansing_steps":"Survivor = record with the most complete KYC data\nOld customer numbers kept as alternate keys\nAccounts and contracts re-pointed to the survivor","approval_needed":false,"target_completion_date":"2026-11-07","records_corrected":26450,"progress_percent":96,"quality_target_percent":100,"progress_log":"2026-09-20\t9,800\t17,750\tFirst automated merge run\n2026-10-15\t21,300\t6,250\tBranch review of fuzzy matches\n2026-11-01\t26,450\t1,100\tRemaining cases with conflicting IDs","verification_method":"Re-run the duplicate check on the Mock 2 extract\nSample of 100 merged customers checked by the data owner","open_issues":"1,100 pairs with conflicting identity numbers need branch confirmation","notes":"Merge rules signed off by the business data owner on 2026-09-18"}$j$),
