  ('00000000-0000-4000-a010-000000000003', $j${"issue_reference":"DQ-003","product_area":"customers_individual_and_corporate","data_object":"Customer","source_system":"Legacy core banking – Instances 1 and 2","issue_category":"missing_mandatory","severity":"critical","blocks_migration":true,"found_during":"profiling","data_owner":"Amina Diallo","cleansing_lead":"Brian Otieno","records_checked":1400000,"records_affected":61200,"detection_rule":"Industry, sector, customer status, account officer, target market, nationality or residence empty or not in the target code lists","impact_if_not_fixed":"Customer records rejected by the target load","affected_mapping_sheets":"DMS-CUS-01","cleansing_method":"fix_at_source","responsible_team":"Branch operations","cleansing_steps":"Defaults agreed for sector and target market by customer type\nAccount officer reassigned for staff who left\nRemaining records corrected by branches","approval_needed":false,"target_completion_date":"2026-09-30","actual_completion_date":"2026-09-26","records_corrected":61200,"progress_percent":100,"quality_target_percent":100,"progress_log":"2026-09-01\t40,000\t21,200\tDefaults applied\n2026-09-26\t61,200\t0\tAll corrected","verified_in":"mock_1","verified_by":"Amina Diallo","verification_date":"2026-10-02","residual_exceptions":0,"residual_risk_accepted":false,"verification_method":"Mandatory field check on the Mock 1 load — no rejections for these fields","open_issues":"None","notes":"Default rules recorded in DMS-CUS-01"}$j$),
  ('00000000-0000-4000-a010-000000000004', $j${"issue_reference":"DQ-004","product_area":"dormant_and_inactive_accounts","data_object":"Customer accounts","source_system":"Legacy core banking – Instance 1 (retail and SME)","issue_category":"closure_candidate","severity":"medium","blocks_migration":false,"found_during":"business_review","data_owner":"Nomvula Khumalo","cleansing_lead":"Kevin Mutua","records_checked":2150000,"records_affected":18700,"value_affected":4200000,"detection_rule":"Last customer debit and credit more than 5 years before the migration date","impact_if_not_fixed":"Unclaimed balances migrated into live products","affected_mapping_sheets":"DMS-ACC-01","cleansing_method":"close_before_migration","responsible_team":"Branch operations with Finance","cleansing_steps":"Final notice to customers where an address exists\nBalances transferred to the unclaimed balances account per regulation\nAccounts closed in the legacy system","approval_needed":true,"target_completion_date":"2026-11-30","records_corrected":0,"progress_percent":0,"quality_target_percent":100,"progress_log":"2026-11-02\t0\t18,700\tRegulatory notice period running","verification_method":"Dormancy report on the Mock 3 extract shows no account dormant for more than 5 years","open_issues":"Regulator confirmation of the transfer procedure pending","notes":"Operations to process in November"}$j$),
  ('00000000-0000-4000-a010-000000000005', $j${"issue_reference":"DQ-005","product_area":"term_fixed_deposits","data_object":"Deposits","source_system":"Legacy core banking – Instances 1 and 2","issue_category":"business_rule","severity":"high","blocks_migration":true,"found_during":"mock_1","data_owner":"Catherine Mwangi","cleansing_lead":"Ravi Pillai","records_checked":185000,"records_affected":1320,"value_affected":38500000,"detection_rule":"Maturity date before the migration date and principal greater than zero","impact_if_not_fixed":"Matured deposits cannot be loaded as running deposits","affected_mapping_sheets":"DMS-DEP-01; DMS-DEP-02/03","cleansing_method":"fix_at_source","responsible_team":"Treasury back office","cleansing_steps":"Customers asked to roll over or withdraw\nUnclaimed matured deposits paid to the settlement account\nRemaining: maturity moved to the migration date (mature again at first close of business)","approval_needed":true,"target_completion_date":"2027-03-31","records_corrected":870,"progress_percent":66,"quality_target_percent":100,"progress_log":"2026-10-10\t410\t910\tCustomer instructions received\n2026-11-05\t870\t450\tPayouts to settlement accounts","verification_method":"Matured-deposit check on each mock extract","open_issues":"Deposits without settlement accounts need a branch visit","notes":"Rule agreed with the deposits product owner"}$j$),
  ('00000000-0000-4000-a010-000000000006', $j${"issue_reference":"DQ-006","product_area":"loans_and_lending_arrangements","data_object":"Loans","source_system":"Legacy core banking – Instances 1 and 2","issue_category":"business_rule","severity":"high","blocks_migration":true,"found_during":"profiling","data_owner":"Joy Akinyi","cleansing_lead":"Ravi Pillai","records_checked":240000,"records_affected":8900,"detection_rule":"More than one repayment account per customer and currency","impact_if_not_fixed":"Automated repayments fail in the target","affected_mapping_sheets":"DMS-LND-01","cleansing_method":"transform_in_staging","responsible_team":"Credit operations","cleansing_steps":"Remap loans to the customer primary account in that currency\nCustomer consent checked where the account changes","approval_needed":true,"target_completion_date":"2026-10-31","actual_completion_date":"2026-10-24","records_corrected":8900,"progress_percent":100,"quality_target_percent":100,"progress_log":"2026-10-05\t5,200\t3,700\tConsents confirmed\n2026-10-24\t8,900\t0\tAll remapped","verified_in":"mock_2","verified_by":"Joy Akinyi","verification_date":"2026-11-14","residual_exceptions":0,"residual_risk_accepted":false,"verification_method":"Repayment account check on the Mock 2 load","open_issues":"None","notes":"Consent letters filed with the loan documents"}$j$),
  ('00000000-0000-4000-a010-000000000007', $j${"issue_reference":"DQ-007","product_area":"customer_delivery_addresses_and_advice_preferences","data_object":"Delivery addresses","source_system":"Legacy core banking – Instance 2 (corporate and treasury)","issue_category":"invalid_reference","severity":"medium","blocks_migration":false,"found_during":"profiling","data_owner":"Ravi Pillai","cleansing_lead":"Kwame Asante","records_checked":2300,"records_affected":340,"detection_rule":"Bank identifier code not found in the current directory","impact_if_not_fixed":"Outgoing messages rejected","affected_mapping_sheets":"DMS-DEL-01","cleansing_method":"fix_at_source","responsible_team":"Payments operations","cleansing_steps":"Directory refreshed\nOutdated codes replaced with the successor code","approval_needed":false,"target_completion_date":"2026-09-30","actual_completion_date":"2026-09-18","records_corrected":340,"progress_percent":100,"quality_target_percent":100,"progress_log":"2026-09-18\t340\t0\tAll codes replaced","verified_in":"mock_1","verified_by":"Ravi Pillai","verification_date":"2026-09-25","residual_exceptions":0,"residual_risk_accepted":false,"verification_method":"Directory check on the Mock 1 extract","open_issues":"None","notes":"Directory refreshed again in the week before go-live"}$j$),
  ('00000000-0000-4000-a010-000000000008', $j${"issue_reference":"DQ-008","product_area":"current_and_savings_accounts","data_object":"Customer accounts","source_system":"Legacy core banking – Instances 1 and 2","issue_category":"closure_candidate","severity":"low","blocks_migration":false,"found_during":"mock_1","data_owner":"Nomvula Khumalo","cleansing_lead":"Kevin Mutua","records_checked":2150000,"records_affected":2450,"detection_rule":"Accounts flagged for closure with zero balance","impact_if_not_fixed":"Unwanted empty accounts created in the target","affected_mapping_sheets":"DMS-ACC-01","cleansing_method":"close_before_migration","responsible_team":"Branch operations","cleansing_steps":"Closure completed in the legacy system before the freeze\nExcluded by the selection rule if still open","approval_needed":false,"target_completion_date":"2027-03-31","records_corrected":1600,"progress_percent":65,"quality_target_percent":100,"progress_log":"2026-10-20\t900\t1,550\tBranch batch 1\n2026-11-04\t1,600\t850\tBranch batch 2","verification_method":"Closure flag check on each mock extract","open_issues":"None","notes":"Low risk: the selection rule excludes these accounts anyway"}$j$),
  ('00000000-0000-4000-a010-000000000009', $j${"issue_reference":"DQ-009","product_area":"customer_images_signatures_and_mandates","data_object":"KYC documents","source_system":"Customer due diligence repository","issue_category":"outdated","severity":"medium","blocks_migration":false,"found_during":"business_review","data_owner":"Nadia Rahman","cleansing_lead":"Priya Naidoo","records_checked":1150000,"records_affected":96000,"detection_rule":"Identity document expired or proof of address older than 3 years for active customers","impact_if_not_fixed":"Non-compliant KYC carried into the target","affected_mapping_sheets":"DMS-CUS-01; DMS-IMG-01","cleansing_method":"fix_after_migration","responsible_team":"Compliance with branch customer service","cleansing_steps":"Customers flagged in the target for KYC refresh\nRemediation campaign after go-live","approval_needed":false,"target_completion_date":"2027-09-30","records_corrected":12000,"progress_percent":13,"quality_target_percent":95,"progress_log":"2026-10-31\t12,000\t84,000\tRemediation through branch visits","verification_method":"Flag present on every affected customer in the Mock 2 load","open_issues":"Remediation plan to be approved by Compliance","notes":"Migration is not blocked"}$j$),
  ('00000000-0000-4000-a010-00000000000a', $j${"issue_reference":"DQ-010","product_area":"credit_limits_and_facilities","data_object":"Limits","source_system":"Legacy core banking – Instance 2 (corporate and treasury)","issue_category":"outdated","severity":"high","blocks_migration":true,"found_during":"mock_1","data_owner":"Joy Akinyi","cleansing_lead":"Ravi Pillai","records_checked":96000,"records_affected":2180,"value_affected":1250000000,"detection_rule":"Limit expiry date on or before the migration date with a running contract linked","impact_if_not_fixed":"Target rejects expired limits, so linked contracts cannot load","affected_mapping_sheets":"DMS-LIM-01","cleansing_method":"fix_at_source","responsible_team":"Credit risk","cleansing_steps":"Credit reviews each limit: renew or let expire\nNot renewed: migration rule (expiry = migration date + 1 day, original kept in a local field)","approval_needed":true,"target_completion_date":"2027-02-28","records_corrected":0,"progress_percent":0,"quality_target_percent":100,"progress_log":"2026-11-03\t0\t2,180\tCredit review scheduled","verification_method":"Expired-limit check on the Mock 3 extract","open_issues":"Credit committee capacity for 2,180 reviews","notes":"Rule documented in DMS-LIM-01"}$j$)
) AS v(id, vals)
WHERE r.id = v.id::uuid AND r.is_deleted = FALSE;

-- Check: filled fields per sample issue.
SELECT display_id, title, status, (SELECT count(*) FROM jsonb_object_keys(field_values)) AS fields_filled
FROM public.local_register_records
WHERE register_id = '00000000-0000-4000-9001-000000000010'::uuid AND id::text LIKE '00000000-0000-4000-a010-%'
ORDER BY id;
